from casing import camel_to_snake


def test_simple_camel_case():
    assert camel_to_snake("simpleWord") == "simple_word"


def test_leading_acronym():
    assert camel_to_snake("HTTPServer") == "http_server"


def test_trailing_acronym():
    assert camel_to_snake("userID") == "user_id"


def test_no_boundaries_unchanged():
    assert camel_to_snake("lowercase") == "lowercase"


def test_multiple_words():
    assert camel_to_snake("getUserIDFromRequest") == "get_user_id_from_request"

