from casing import camel_to_snake


def test_lowercase_result():
    assert camel_to_snake("simpleWord").islower()


def test_no_spaces():
    assert " " not in camel_to_snake("simpleWord")


def test_length_reasonable():
    assert len(camel_to_snake("userID")) >= 6


def test_unchanged_when_already_lower():
    assert camel_to_snake("plain") == "plain"
